// Link-only stand-ins for unreachable rendering/guest services retained by the
// whole nvn_mtl.m translation unit. Each entry traps if accidentally reached.
// Explicit list: new unresolved dependencies fail the link, never auto-stubbed.
// No argument or return ABI is assumed: these entries never return.
.text
.macro UNUSED name
.globl _\name
.p2align 2
_\name:
    brk #0
.endmacro

